import{z as i,x as s,o as l,c as A,q as e,j as o,D as t,d as n,s as r,S as B}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Huang-Stoll 价差分解估计","description":"","frontmatter":{"title":"Huang-Stoll 价差分解估计","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/huang-stoll-spread.md","filePath":"quant/huang-stoll-spread.md","lastUpdated":1791063341000}'),p={name:"quant/huang-stoll-spread.md"};function h(d,a,u,c,m,_){const E=s("Mermaid");return l(),A("div",null,[a[2]||(a[2]=e('<h1 id="huang-stoll-价差分解估计" tabindex="-1">Huang-Stoll 价差分解估计 <a class="header-anchor" href="#huang-stoll-价差分解估计" aria-label="Permalink to &quot;Huang-Stoll 价差分解估计&quot;">​</a></h1><div class="epigraph"><p>把价差拆成逆向选择、存货与订单处理，需要成交方向的序列，而不仅仅是一个平均宽度。方向如何分类，分解出的份额就会跟着走。</p><footer>—— Huang and Stoll, The Components of the Bid-Ask Spread: A General Approach, Journal of Financial Economics, 1997</footer></div><p><a href="/quant/tick-quote-rule">Tick / Quote 规则</a>给出方向 \\(D_t\\)。本课的缺口是：有了方向，如何把先修课序里概念上的三项——逆向选择、存货、订单处理——写成可估计的回归，而不是停留在有效减实现的约化会计。<a href="/quant/effective-realized-spread">有效价差与实现价差</a>已经能把冲击从实现收入里分开，但它不分离存货与处理。Huang 与 Stoll（1997）用成交方向的自相关与报价调整，给出两路和三路分解。本课不重写 <a href="/quant/roll-model">Roll</a> 的协方差开方，也不重写 <a href="/quant/kyle-model">Kyle</a> 的 \\(\\lambda\\)；那些是另一套识别。后课 MRR、Corwin–Schultz 是并列估计器，本课只把 Huang–Stoll 的设定读清楚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>概念分解 \\(s=s_{\\mathrm{as}}+s_{\\mathrm{inv}}+s_{\\mathrm{proc}}\\) 三项都不可直接观测。有效减实现把永久中点移动当成冲击，冲击里仍混合逆向选择与未衰减的存货压力。要分开存货与处理，需要额外的矩：方向是否自相关、报价中点是否随累积方向偏移、价差是否随方向状态改变。Huang–Stoll 的一般方法是：把观察到的成交价变化写成方向的函数，约束来自做市商报价行为。缺口是这套约束依赖 \\(D_t\\) 测得准——上一课刚说明中点附近 tick 规则与报价规则会分叉。分解份额对分类噪声敏感，不是对「理论三项」敏感。</p><p><span class="marginnote">三个名词先翻译成大白话：逆向选择=「和我成交的对手可能比我懂」，吃亏要补偿；存货=「成交让我攒下一堆货，货有风险」；订单处理=「每处理一笔单子的固定开销——系统、清算、人力」。三项加起来才等于整个价差。</span></p><p>两路分解把存货并入暂时成分，只估逆向选择对价差的比例 \\(\\theta\\) 与暂时成分 \\(1-\\theta\\)。三路再试图把暂时成分拆成存货与处理。识别更强，失败也更常见：方向负自相关既可来自买卖回跳（处理），也可来自存货诱导的反向成交。没有头寸数据时，三路经常不稳定。问题是先报告两路，三路当敏感性，而不是一上来输出三色饼图。</p>',7)),(l(),o(B,null,{default:t(()=>[r(E,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20AS%5B%22%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%EF%BC%9A%E6%88%90%E4%BA%A4%E6%8F%AD%E7%A4%BA%E4%BF%A1%E6%81%AF%22%5D%20--%3E%20P1%5B%22%E6%8C%87%E7%BA%B9%EF%BC%9A%E6%88%90%E4%BA%A4%E5%90%8E%E4%B8%AD%E7%82%B9%E6%B0%B8%E4%B9%85%E7%A7%BB%E5%8A%A8%EF%BC%8C%E5%9B%9E%E8%B7%B3%E6%B6%88%E5%A4%B1%22%5D%0A%20%20INV%5B%22%E5%AD%98%E8%B4%A7%EF%BC%9A%E5%81%9A%E5%B8%82%E5%95%86%E6%83%B3%E5%8D%B8%E5%A4%B4%E5%AF%B8%22%5D%20--%3E%20P2%5B%22%E6%8C%87%E7%BA%B9%EF%BC%9A%E6%8A%A5%E4%BB%B7%E8%AF%B1%E5%AF%BC%E5%8F%8D%E5%90%91%E6%88%90%E4%BA%A4%EF%BC%8C%E6%96%B9%E5%90%91%E8%B4%9F%E8%87%AA%E7%9B%B8%E5%85%B3%22%5D%0A%20%20PR%5B%22%E8%AE%A2%E5%8D%95%E5%A4%84%E7%90%86%EF%BC%9A%E6%AF%8F%E7%AC%94%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%22%5D%20--%3E%20P3%5B%22%E6%8C%87%E7%BA%B9%EF%BC%9A%E4%B8%8E%E6%96%B9%E5%90%91%E7%8A%B6%E6%80%81%E6%97%A0%E5%85%B3%E7%9A%84%20Roll%20%E5%BC%8F%E5%9B%9E%E8%B7%B3%22%5D%0A%20%20P1%20--%3E%20S%5B%22%E4%B8%89%E7%A7%8D%E6%8C%87%E7%BA%B9%E5%8F%A0%E5%8A%A0%20%3D%20%E8%A7%82%E6%B5%8B%E5%88%B0%E7%9A%84%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20P2%20--%3E%20S%0A%20%20P3%20--%3E%20S%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="方向方程与价差方程是一套-不是两个独立回归" tabindex="-1">方向方程与价差方程是一套，不是两个独立回归 <a class="header-anchor" href="#方向方程与价差方程是一套-不是两个独立回归" aria-label="Permalink to &quot;方向方程与价差方程是一套，不是两个独立回归&quot;">​</a></h3><p>Huang–Stoll 把成交方向的条件期望与报价调整联立。方向的一阶自相关进入存货项：若做市商用报价诱导反向成交，观测到的 \\(D_t\\) 应对 \\(-D_{t-1}\\) 有反应。若只有处理成本、买卖随机，方向近似白噪声，成交价出现 Roll 式回跳。若只有逆向选择，成交后报价永久移动，回跳消失。把这三种极端写进同一个线性结构，系数才被解释成份额。单独把 \\(D_t\\) 对 \\(D_{t-1}\\) 回归，或单独把 \\(\\Delta p\\) 对 \\(D\\) 回归，都不是原文的分解。</p><p><span class="marginnote">\\(D_t\\) 必须与报价同步。用本所成交对本所 BBO 分类，再拿去和 NBBO 中点变分回归，系数没有定义。碎片化样本里先锁报价源，再跑 Huang–Stoll。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：清洗后的成交价、同期买卖报价、方向序列。方向用报价规则优先、平价用 tick，或用交易所主动标志当对照。估计两路：允许逆向选择比例 \\(\\theta\\)，暂时成分吸收处理加存货。再估计三路：加入方向自相关结构以分离存货。报告 \\(\\theta\\)、存货份额、处理份额，以及方向自相关、平均报价价差。Huang–Stoll（1997）原文用的是当时纽约与纳斯达克样本；你的复制必须换现代小数报价、多场所数据，数字不会也不应等于 1997 年表格。</p><p><span class="marginnote">数字实例：若估出 \\(\\theta=0.3\\)，意思是 10 分钱的价差里，约 3 分钱是补偿「对手可能知情」的部分（做市商长期要亏掉的），另外 7 分钱是暂时成分——成交后还能靠回跳赚回来的部分。\\(\\theta\\) 越高的股票，挂限价单越危险。</span></p><p>对照约化统计量：同一 \\(\\tau\\) 上的实现价差份额应与两路里的暂时成分同方向变化，但不必数值相等——窗口 \\(\\tau\\) 与模型里的「下一笔」不是同一地平线。这正是后课<a href="/quant/realized-spread-horizon">实现价差期限</a>要展开的。不要用 PIN 的知情概率去「验证」\\(\\theta\\)：PIN 是混合分布的参数，Huang–Stoll 是价差份额，量纲不同。</p><h3 id="分类错误把逆向选择往下压" tabindex="-1">分类错误把逆向选择往下压 <a class="header-anchor" href="#分类错误把逆向选择往下压" aria-label="Permalink to &quot;分类错误把逆向选择往下压&quot;">​</a></h3><p>随机分错方向，相当于 \\(D\\) 乘了一个小于 1 的信度。与 \\(D\\) 相关的报价调整被缩小，\\(\\theta\\) 偏低，处理项偏高。中点成交占比高的股票（一 tick 价差、大量内部化）误差最大。Ellis–Michaely–O&#39;Hara 的分层精度应作为分解的质量警告：在中点层单独估一套，不要只报全样本。用官方主动标志的子样本做 bound，比调模型阶数更有用。</p><p><span class="marginnote">常见误区：初学者容易以为 tick 规则和报价规则只是实现细节。同一笔成交（买价抬一下之后的卖成交）在两套规则下可以方向相反，而整个分解的输入就是方向序列——分类错一截，逆向选择份额就跟着被压低一截，这不是调参数能救的。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>逆向选择项对应成交后信念更新：买成交之后公允价格上移，卖则下移，做市商的事后收入小于报价价差。存货项对应头寸目标：连续被买之后，做市商提高两边报价以诱导卖盘，方向出现负相关，中点出现与累积流量相反的均值回复。处理项对应每笔固定成本，产生不随方向状态改变的回跳。Huang–Stoll 的贡献是把这三种行为写成同一组可估计约束，而不是三个故事各讲一遍。</p><p>与 Glosten–Harris 一类线性模型的差别：后者更贴近把价格变化投影到带符号流量，接近经验 lambda；Huang–Stoll 盯的是价差的构成比例。与 Roll 的差别：Roll 只用成交价协方差，分不出 \\(\\theta\\)。本课需要报价和方向，数据更苛刻，解释更细。</p><p><span class="marginnote">三路里存货与逆向选择都移动中点。差别靠方向的条件结构，不靠「中点动了就是信息」。先修课已经警告过这一点；估计时若存货项为负或超过 100%，应退回两路，而不是改符号限制硬挤出饼图。</span></p>',14)),(l(),o(B,null,{default:t(()=>[r(E,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%96%B9%E5%90%91%20D_t%22%5D%20--%3E%20HS%5B%22Huang-Stoll%20%E7%BB%93%E6%9E%84%22%5D%0A%20%20Q%5B%22%E6%8A%A5%E4%BB%B7%E8%B0%83%E6%95%B4%22%5D%20--%3E%20HS%0A%20%20HS%20--%3E%20AS%5B%22%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%E4%BB%BD%E9%A2%9D%20%CE%B8%22%5D%0A%20%20HS%20--%3E%20INV%5B%22%E5%AD%98%E8%B4%A7%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20HS%20--%3E%20PR%5B%22%E5%A4%84%E7%90%86%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20D%20--%3E%20ERR%5B%22%E5%88%86%E7%B1%BB%E5%99%AA%E5%A3%B0%22%5D%0A%20%20ERR%20--%3E%20AS%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h3 id="没有头寸时不要强上三路" tabindex="-1">没有头寸时不要强上三路 <a class="header-anchor" href="#没有头寸时不要强上三路" aria-label="Permalink to &quot;没有头寸时不要强上三路&quot;">​</a></h3><p>三路存货项靠方向自相关识别。限价市场没有专家库存，该项为负或超过百分之百时，应退回两路并写明。强加非负约束只是把识别失败藏进饼图。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有买卖报价时不要做 Huang–Stoll，改 Roll 或 Corwin–Schultz。集合竞价成交没有连续方向结构，应剔除开收盘拍卖。涨跌停一侧报价缺失，中点与方向同时坏。A 股主订单驱动、没有单一专家存货，存货项应解释为限价群体的集体头寸压力，而不是专家库存；份额仍可估，故事不能照抄 1990 年代纽约。</p><p><span class="marginnote">开收盘拍卖、涨跌停、中点 ATS 打印，都应在估计前剔除或单独成组。把它们丢进方向自相关，处理项会被制度结构污染。</span></p><p>下一课序里的 MRR 用另一组报价更新方程。本课只要你带着「方向序列是分解的输入，分类误差进入份额」进入后面的估计器。实现价差的 \\(\\tau\\) 还没被模型化，那是价格形成课序末尾的课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Huang–Stoll 用方向与报价调整估价差份额；两路稳，三路识别弱。</li><li>不要重跑 Roll 开方或 Kyle lambda 来「代替」该分解。</li><li>方向分类噪声系统性压低逆向选择份额。</li><li>冲击的约化度量（有效减实现）与 \\(\\theta\\) 同方向，但地平线不同。</li><li>存货项在限价市场里是集体头寸，不是单一专家。</li><li>出处：Huang and Stoll, <em>Journal of Financial Economics</em>, 1997；方向精度见 Ellis, Michaely and O&#39;Hara, <em>JFQA</em>, 2000；概念三项见 O&#39;Hara, <em>Market Microstructure Theory</em>。</li></ul>',8))])}const g=i(p,[["render",h]]);export{S as __pageData,g as default};
